el class="form-label">Login email</label><input type="email" name="login_email" value="<?php echo e(old('login_email',$warehouseAdmin?->email)); ?>" class="form-control" required></div><div class="col-md-6"><label class="form-label"><?php echo e($editing ? 'New password (leave empty to keep current)' : 'Password'); ?></label><input type="password" name="login_password" class="form-control" <?php echo e($editing ? '' : 'required'); ?>></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" value="1" <?php if(old('is_active',$warehouse->is_active)): echo 'checked'; endif; ?>> Active warehouse</label></div><div class="col-12"><button class="btn text-white" style="background:var(--brand)"><?php echo e($editing?'Update warehouse':'Create warehouse & login'); ?></button></div></div></div></form>
